import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

public class PaymentService {
    // one logger per class, named com.app.PaymentService
    private static final Logger log = LoggerFactory.getLogger(PaymentService.class);

    public void pay(long orderId, double amount) {
        log.info("Charging order {} for {}", orderId, amount); // parameterized, no '+'
        if (amount <= 0) {
            log.warn("Non-positive amount {} for order {}", amount, orderId);
            return;
        }
        try {
            gateway.charge(amount);
        } catch (Exception e) {
            log.error("Charge failed for order {}", orderId, e); // exception last = stack trace
        }
    }
}
